select
  id, type, user_id, name, evaluation_scores, evaluation_desc, create_time
from app_satisfaction_evaluation


        and id = #{appSatisfactionEvaluation.id}


        and type = #{appSatisfactionEvaluation.type}


        and user_id = #{appSatisfactionEvaluation.userId}


        and name = #{appSatisfactionEvaluation.name}


        and evaluation_scores = #{appSatisfactionEvaluation.evaluationScores}


        and evaluation_desc = #{appSatisfactionEvaluation.evaluationDesc}


        and create_time = #{appSatisfactionEvaluation.createTime}


order by id desc
limit #{pageable.pageSize} OFFSET #{pageable.offset}

select count(1)
from app_satisfaction_evaluation


        and id = #{id}


        and type = #{type}


        and user_id = #{userId}


        and name = #{name}


        and evaluation_scores = #{evaluationScores}


        and evaluation_desc = #{evaluationDesc}


        and create_time = #{createTime}
